package vm

// golang.org/x/sys/unix from the host.
//
// Plugins import golang.org/x/sys/unix through gRPC, zap (go-isatty),
// wazero, the OpenTelemetry SDK... Run from source, its system calls go
// through assembly (Syscall6 on linux) or through the C library (darwin,
// openbsd), which the VM cannot run: with Options.StubAssembly they return
// ENOSYS, and the plugin works differently from Go.
//
// The host links its own copy of the package. stdsyms.XSysUnix is its symbol
// table on this platform (generated by cmd/stdsyms), and the VM runs the
// package natively (ModeNative) instead of from source, so its system calls
// really run:
//
//   - with the standard library as in Go (Options.Unrestricted and
//     RealProcess, or RunMain without restrictions), the whole package;
//   - in a restricted plugin with Options.UseUnsafe, a read-only subset
//     (xsysunix.go), as for syscall (unsafesyscall.go). A function outside
//     the subset is refused at load time; with Options.StubAssembly it loads
//     as a stub (xsysStub).
//
// Other plugins run it from source as before: without UseUnsafe a
// restricted plugin cannot import it (it imports unsafe), and Unrestricted
// without RealProcess gets no syscall either.
//
// Versions. The plugin was written for the version of x/sys of its go.mod
// (or vendor directory), the host links one version (the one of yaegi v2's
// go.mod, or newer if the host's go.mod says so). The VM uses the host copy
// only when (xsysModes):
//
//   - the plugin's package is from module golang.org/x/sys, not replaced;
//   - its version is not newer than the host's (semver): x/sys keeps its API
//     from one version to the next, and the system calls are the ABI of the
//     kernel, so an older plugin gets the same calls with the fixes of the
//     newer version;
//   - the host's x/sys is not replaced either;
//   - every function, method, type and variable of the package that the
//     plugin's code uses exists in the host copy with the same type (same
//     signature, same fields of the same types, the same layout). So the
//     values that cross the boundary have the same shape on both sides.
//
// Otherwise the package runs from source as before, and
// Machine.NativeFallback says why. This is less strict than the AOT copies
// (aotsource.go: exact version and sources): an AOT copy runs the code of the
// library on the plugin's types, x/sys/unix is a thin layer over system calls
// whose API does not change. A fork that keeps the import path (a replace
// directive) is never replaced by the host copy.

import (
	"fmt"
	"go/types"
	"reflect"
	"runtime/debug"
	"sort"
	"strings"
	"sync"

	"golang.org/x/mod/semver"

	"github.com/traefik/yaegi/v2/stdsyms"
)

const (
	xsysUnixPath = "golang.org/x/sys/unix"
	xsysModule   = "golang.org/x/sys"
)

func init() {
	if t := stdsyms.XSysUnix; t != nil {
		RegisterNativePackage(&Package{Path: xsysUnixPath, Funcs: t.Funcs, Types: t.Types, Vars: t.Vars, Module: xsysModule, Version: t.Version})
	}
}

// hostXSys returns the version of golang.org/x/sys that the host links, or
// why the host copy cannot be used. A binary built by the go command records
// its modules; a test binary does not, and then the version is the one the
// table was generated from (yaegi v2's go.mod).
var hostXSys = sync.OnceValues(func() (version, why string) {
	if natPkg(xsysUnixPath) == nil {
		return "", "yaegi v2 has no table of golang.org/x/sys/unix on this platform"
	}
	if bi, ok := debug.ReadBuildInfo(); ok {
		for _, d := range bi.Deps {
			if d.Path == xsysModule {
				if d.Replace != nil {
					return "", "the host replaces module golang.org/x/sys"
				}
				return d.Version, ""
			}
		}
	}
	return stdsyms.XSysUnix.Version, ""
})

// xsysWanted reports whether a plugin loaded with opts gets
// golang.org/x/sys/unix from the host: the whole package with the standard
// library as in Go, the read-only subset in a restricted plugin with
// UseUnsafe.
func (opts Options) xsysWanted() bool {
	return opts.realStd() || opts.restricted() && opts.UseUnsafe
}

// xsysModes returns modes with ModeNative for golang.org/x/sys/unix when want
// is true, the plugin's sources src have the package, modes has no explicit
// mode for it, and the host copy can run the plugin's version (see the top
// of this file). Otherwise it returns modes, and the reason when the package
// stays interpreted. modes itself is not changed.
func xsysModes(modes map[string]Mode, want bool, src []sourcePkg, info func(string) (srcInfo, bool)) (map[string]Mode, map[string]string) {
	if !want {
		return modes, nil
	}
	if _, ok := modes[xsysUnixPath]; ok {
		return modes, nil
	}
	found := false
	for _, sp := range src {
		if sp.types.Path() == xsysUnixPath {
			found = true
			break
		}
	}
	if !found {
		return modes, nil
	}
	if why := xsysMismatch(info, src); why != "" {
		return modes, map[string]string{xsysUnixPath: why}
	}
	out := make(map[string]Mode, len(modes)+1)
	for k, v := range modes {
		out[k] = v
	}
	out[xsysUnixPath] = ModeNative
	return out, nil
}

// xsysMismatch returns why the host copy of golang.org/x/sys/unix cannot run
// the plugin's version of the package, or "".
func xsysMismatch(info func(string) (srcInfo, bool), src []sourcePkg) string {
	host, why := hostXSys()
	if why != "" {
		return why
	}
	si, ok := info(xsysUnixPath)
	switch {
	case !ok || si.module == "":
		return "the plugin's " + xsysUnixPath + " has no module version"
	case si.module != xsysModule:
		return fmt.Sprintf("the plugin's %s is from module %s", xsysUnixPath, si.module)
	case si.replaced:
		return "the plugin replaces module " + xsysModule + " (go.mod replace directive)"
	case !semver.IsValid(si.version) || !semver.IsValid(host):
		return fmt.Sprintf("cannot compare the versions of %s: the plugin's %q, the host's %q", xsysModule, si.version, host)
	case semver.Compare(si.version, host) > 0:
		return fmt.Sprintf("the plugin uses %s %s, newer than the host's %s", xsysModule, si.version, host)
	}
	if bad := xsysAPIMismatch(natPkg(xsysUnixPath), src); len(bad) > 0 {
		if len(bad) > 3 {
			bad = append(bad[:3], fmt.Sprintf("and %d more", len(bad)-3))
		}
		return fmt.Sprintf("the plugin's %s %s does not have the API of the host's %s: %s", xsysModule, si.version, host, strings.Join(bad, "; "))
	}
	return ""
}

// xsysAPIMismatch lists the objects of golang.org/x/sys/unix that the
// packages of src use (outside the package itself) and that the host table
// tab does not have with the same type.
func xsysAPIMismatch(tab *Package, src []sourcePkg) []string {
	seen := map[shapePair]bool{}
	bad := map[string]bool{}
	for _, sp := range src {
		if sp.info == nil || sp.types.Path() == xsysUnixPath {
			continue
		}
		for _, obj := range sp.info.Uses {
			if obj.Pkg() == nil || obj.Pkg().Path() != xsysUnixPath {
				continue
			}
			if r := xsysObjMismatch(tab, obj, seen); r != "" {
				bad[r] = true
			}
		}
	}
	out := make([]string, 0, len(bad))
	for r := range bad {
		out = append(out, r)
	}
	sort.Strings(out)
	return out
}

// xsysObjMismatch returns why obj, an object of golang.org/x/sys/unix, has
// no counterpart of the same type in tab, or "".
func xsysObjMismatch(tab *Package, obj types.Object, seen map[shapePair]bool) string {
	switch o := obj.(type) {
	case *types.Func:
		sig := o.Type().(*types.Signature)
		if recv := sig.Recv(); recv != nil {
			t := recv.Type()
			if p, ok := t.(*types.Pointer); ok {
				t = p.Elem()
			}
			n, ok := types.Unalias(t).(*types.Named)
			if !ok {
				return ""
			}
			rt, ok := tab.Types[n.Obj().Name()]
			if !ok {
				return "type " + n.Obj().Name() + " is missing"
			}
			if types.IsInterface(n) {
				if !sameShape(n, rt, seen) {
					return "type " + n.Obj().Name() + " differs"
				}
				return ""
			}
			m, ok := reflect.PointerTo(rt).MethodByName(o.Name())
			if !ok {
				return "method " + n.Obj().Name() + "." + o.Name() + " is missing"
			}
			if !sameSig(sig, m.Type, 1, seen) {
				return "method " + n.Obj().Name() + "." + o.Name() + " differs"
			}
			return ""
		}
		f, ok := tab.Funcs[o.Name()]
		if !ok {
			return "func " + o.Name() + " is missing"
		}
		if sig.TypeParams().Len() > 0 || !sameShape(sig, f.Type(), seen) {
			return "func " + o.Name() + " differs"
		}
	case *types.Var:
		if o.IsField() {
			return "" // checked with its struct type
		}
		v, ok := tab.Vars[o.Name()]
		if !ok {
			return "var " + o.Name() + " is missing"
		}
		if !sameShape(o.Type(), v.Type().Elem(), seen) {
			return "var " + o.Name() + " differs"
		}
	case *types.TypeName:
		rt, ok := tab.Types[o.Name()]
		if !ok {
			return "type " + o.Name() + " is missing"
		}
		if !sameShape(o.Type(), rt, seen) {
			return "type " + o.Name() + " differs"
		}
	}
	return "" // constants are compiled in
}

// shapePair is a pair of types that sameShape compares.
type shapePair struct {
	t  types.Type
	rt reflect.Type
}

// basicKinds maps the basic types of go/types to the kinds of reflect.
var basicKinds = map[types.BasicKind]reflect.Kind{
	types.Bool: reflect.Bool, types.Int: reflect.Int, types.Int8: reflect.Int8, types.Int16: reflect.Int16,
	types.Int32: reflect.Int32, types.Int64: reflect.Int64, types.Uint: reflect.Uint, types.Uint8: reflect.Uint8,
	types.Uint16: reflect.Uint16, types.Uint32: reflect.Uint32, types.Uint64: reflect.Uint64,
	types.Uintptr: reflect.Uintptr, types.Float32: reflect.Float32, types.Float64: reflect.Float64,
	types.Complex64: reflect.Complex64, types.Complex128: reflect.Complex128, types.String: reflect.String,
	types.UnsafePointer: reflect.UnsafePointer,
}

// sameShape reports whether the type t of the plugin's source of
// golang.org/x/sys/unix is the native type rt of the host's copy: the same
// named types (by package and name; the named types of x/sys/unix also
// with the same underlying type), and the same structure otherwise. seen
// stops the walk on recursive types.
func sameShape(t types.Type, rt reflect.Type, seen map[shapePair]bool) bool {
	if n, ok := types.Unalias(t).(*types.Named); ok {
		obj := n.Obj()
		if obj.Pkg() == nil {
			return rt == errorType // error, the only named type of the universe here
		}
		if n.TypeArgs().Len() > 0 || rt.Name() != obj.Name() || rt.PkgPath() != obj.Pkg().Path() {
			return false
		}
		if obj.Pkg().Path() != xsysUnixPath {
			return true // the standard library of the host
		}
		k := shapePair{n, rt}
		if seen[k] {
			return true
		}
		seen[k] = true
		return sameUnder(n.Underlying(), rt, seen)
	}
	if rt.PkgPath() != "" {
		return false // a named native type for an unnamed type
	}
	return sameUnder(types.Unalias(t), rt, seen)
}

// sameUnder compares the structure of t, not a named type, with rt.
func sameUnder(t types.Type, rt reflect.Type, seen map[shapePair]bool) bool {
	switch u := t.(type) {
	case *types.Basic:
		k, ok := basicKinds[u.Kind()]
		return ok && k == rt.Kind()
	case *types.Pointer:
		return rt.Kind() == reflect.Pointer && sameShape(u.Elem(), rt.Elem(), seen)
	case *types.Slice:
		return rt.Kind() == reflect.Slice && sameShape(u.Elem(), rt.Elem(), seen)
	case *types.Array:
		return rt.Kind() == reflect.Array && int64(rt.Len()) == u.Len() && sameShape(u.Elem(), rt.Elem(), seen)
	case *types.Map:
		return rt.Kind() == reflect.Map && sameShape(u.Key(), rt.Key(), seen) && sameShape(u.Elem(), rt.Elem(), seen)
	case *types.Chan:
		return rt.Kind() == reflect.Chan && chanDir(u.Dir()) == rt.ChanDir() && sameShape(u.Elem(), rt.Elem(), seen)
	case *types.Struct:
		if rt.Kind() != reflect.Struct || rt.NumField() != u.NumFields() {
			return false
		}
		for i := 0; i < u.NumFields(); i++ {
			f, sf := u.Field(i), rt.Field(i)
			if f.Name() != sf.Name || f.Embedded() != sf.Anonymous || !sameShape(f.Type(), sf.Type, seen) {
				return false
			}
		}
		return true
	case *types.Signature:
		return sameSig(u, rt, 0, seen)
	case *types.Interface:
		if rt.Kind() != reflect.Interface || rt.NumMethod() != u.NumMethods() {
			return false
		}
		for i := 0; i < u.NumMethods(); i++ {
			if _, ok := rt.MethodByName(u.Method(i).Name()); !ok && u.Method(i).Exported() {
				return false
			}
		}
		return true
	}
	return false
}

// sameSig compares the signature sig with the function type rt, whose first
// skip parameters are not in sig (the receiver of a method).
func sameSig(sig *types.Signature, rt reflect.Type, skip int, seen map[shapePair]bool) bool {
	if rt.Kind() != reflect.Func || rt.NumIn()-skip != sig.Params().Len() || rt.NumOut() != sig.Results().Len() || rt.IsVariadic() != sig.Variadic() {
		return false
	}
	for i := 0; i < sig.Params().Len(); i++ {
		if !sameShape(sig.Params().At(i).Type(), rt.In(skip+i), seen) {
			return false
		}
	}
	for i := 0; i < sig.Results().Len(); i++ {
		if !sameShape(sig.Results().At(i).Type(), rt.Out(i), seen) {
			return false
		}
	}
	return true
}

// dropNative returns the packages of src that run from source: without the
// non-standard packages that run natively (golang.org/x/sys/unix of the
// host). The load-time checks apply to these only, as to the standard
// library: the plugin's writes to the variables of a native package are
// writes to the host's variables.
func dropNative(src []sourcePkg, modes map[string]Mode, aot bool) []sourcePkg {
	out := src[:0:0]
	for _, sp := range src {
		if p := sp.types.Path(); !isStdPath(p) && ModeFor(modes, aot, p) == ModeNative {
			continue
		}
		out = append(out, sp)
	}
	return out
}
